update_rule.pseudocode:
if day == 0:
  if network_model == 'small_world':
    create Watts-Strogatz graph(n=population_size, k=average_degree, p=rewiring_probability)
  else if network_model == 'erdos_renyi':
    create G(n, p=average_degree/(n-1))
  else if network_model == 'scale_free':
    create Barabasi-Albert graph with m=average_degree/2
  assign neighbor lists to each Person
else:
  no-op

if day == mandate_day:
  government.mandate_active = True
if government.mandate_active:
  set mask_requirement=True for a fraction=location_mask_requirement_share of locations
  for each location L:
    L.enforcement_level = mandate_enforcement_rate * location_enforcement_level_default
  allocate enforcement checks proportional to enforcement_resources and location occupancy
  for each person present in enforced locations without mask:
    with prob=warning_probability: issue warning; else issue fine=fine_amount and record in signal.fines_issued_daily
    update person.compliance_propensity += enforcement_deterrence_strength * (fine_amount>0)

shares=0
for each household H:
  # Influence
  adopt_rate_H = mean(member.adoption_state)
  for member i in H:
    i.compliance_propensity += intra_household_influence_weight * H.household_norms_strength * (adopt_rate_H - i.adoption_state)
  # Sharing
  total_stock = sum(member.mask_ownership_count)
  for member i with i.mask_ownership_count < share_minimum_stock_to_share:
    find donor j in H with max stock
    if donor exists and donor.mask_ownership_count > share_minimum_stock_to_share:
      donor.mask_ownership_count -= 1; i.mask_ownership_count += 1; shares += 1
emit signal.household_shares_daily=shares

if not include_disease_dynamics: emit zeros and return
for each contact pair (i,j) sampled to match contact_rate_per_day:
  eff_transmission = beta_base * (1 - mask_effectiveness_against_transmission * (i.adoption_state OR j.adoption_state))
  if one infected and the other susceptible:
    infect with probability eff_transmission
recover infected with probability gamma_recovery
update counts; emit cases_daily and cases_cum
# feedback
population_case_rate = cases_daily / population_size
for each person i: i.risk_perception = clip(i.risk_perception + risk_feedback_from_cases * population_case_rate, 0,1)
